head.script:
// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : 강조 클래스(w2autoComplete_keyword) 를 style 블럭에서 재정의했을 때 강조 스타일 변경
//  - 값별 강조 여부 / 처음 일치하는 한 곳만 강조 / 기본 CSS 항목은 column_P_useKeywordHighlight_1.xml 에서 확인
//  - useKeywordHighlight="true" 고정, 이 페이지의 style 블럭에서 w2autoComplete_keyword 를 파란색 / 보통 굵기 / 밑줄 / 노란 배경으로 재정의
scwin.tData = {
    "description" : "[column > P > useKeywordHighlight]<br/>inputType='autoComplete' 인 Column 에서 검색된 아이템에 사용자의 입력값과 일치하는 부분을 강조하여 표시할지 설정합니다.",
    "validation" : [
        "강조 스타일을 바꾸려면 CSS 파일이나 style 블럭에서 'w2autoComplete_keyword' 클래스를 재정의하여야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 버튼을 누르기 직전(mousedown) 열려 있는 목록을 읽어 둔다
    btn_checkHighlight.render.addEventListener("mousedown", scwin.captureListRows, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name : 안내 Column (readOnly) / city : 검증 대상 autoComplete Column (useKeywordHighlight = true 고정)
//  - 아이템(Label / Value) : Bora Bora / BOR, Baden-Baden / BAD, Barcelona / BCN, Seoul / SEL
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] city Column useKeywordHighlight=true 고정, 이 페이지 style 블럭에서 강조 클래스를 파란색 / 보통 굵기 / 밑줄 / 노란 배경으로 재정의\n[절차] city 셀 더블클릭 -> 입력값을 모두 지우고 B 입력 -> 목록이 열린 상태에서 목록 강조 확인 클릭\n[확인] 강조 부분이 기본 주황색 굵은 글씨가 아닌 재정의한 스타일로 표시되는지"', '', 'label1');

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "city" : "BCN" },
        { "name" : "김철수", "city" : "SEL" },
        { "name" : "이영희", "city" : "BOR" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>Bora Bora</w2:label><w2:value>BOR</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Baden-Baden</w2:label><w2:value>BAD</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Barcelona</w2:label><w2:value>BCN</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>Seoul</w2:label><w2:value>SEL</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:400px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="text" id="column2" value="city (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="autoComplete" id="city" value="" useKeywordHighlight="true">' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 목록 강조 확인
//  - validation 1 : 강조 span 의 글자색 / 굵기 / 밑줄 / 배경색 이 style 블럭 재정의 값인지 확인
//  - 버튼을 누르면 편집이 끝나 목록이 닫히므로, 버튼 mousedown(capture) 시점에 열려 있는 목록을 읽어 두고 onclick 에서 출력한다
//  - city Column 편집 위젯의 목록(itemTable_main)으로 범위를 한정하고, 표시 중인 Row 만 대상으로 한다 (0건이면 이전 tr 이 숨김 상태로 남음)
scwin.gVar = {
    "listLines" : []
}

scwin.captureListRows = function () {
    let selector = "[id*='" + target1.id + "___autoComplete_'][id$='_city_itemTable_main'] tr";
    let rows = Array.prototype.filter.call(document.querySelectorAll(selector), function (tr) {
        return tr.offsetParent !== null && tr.getBoundingClientRect().height > 0;
    });
    let lines = [];
    for (let i = 0; i < rows.length; i++) {
        let spans = rows[i].querySelectorAll("span.w2autoComplete_keyword");
        let line = "Row " + i + " '" + rows[i].textContent.trim() + "' -> 강조 " + spans.length + "개";
        for (let j = 0; j < spans.length; j++) {
            let cs = window.getComputedStyle(spans[j]);
            line += " / '" + spans[j].textContent + "' (class : " + spans[j].className + ", color : " + cs.color + ", font-weight : " + cs.fontWeight + ", text-decoration : " + cs.textDecorationLine + ", background-color : " + cs.backgroundColor + ")";
        }
        lines.push(line);
    }
    scwin.gVar.listLines = lines;
};

scwin.btn_checkHighlight_onclick = function (e) {
    let wfBottom = wf_body_bottom.getObj("scwin");
    let lines = scwin.gVar.listLines;
    if (lines.length === 0) {
        wfBottom.setReturnValue("목록 Row 0개");
        return;
    }
    for (let i = 0; i < lines.length; i++) {
        wfBottom.setReturnValue(lines[i]);
    }
};
